def submit(remote, payload, key):
    """Submit once, reconciling ambiguous writes before any permitted retry."""
    for attempt in range(2):
        try:
            response = remote.submit(payload, key)
        except TimeoutError:
            try:
                response = remote.status(key)
            except TimeoutError:
                return {"state": "unknown", "key": key}

            if response["state"] == "absent":
                if attempt == 0:
                    continue
                return {"state": "unknown", "key": key}

        if response["state"] == "succeeded":
            return response
        if response["state"] == "pending":
            return {"state": "pending", "key": key}

    return {"state": "unknown", "key": key}
